package com.mlserve.auth

import akka.http.scaladsl.server.Directives._
import akka.http.scaladsl.server.Route
import akka.http.scaladsl.model._
import akka.http.scaladsl.model.headers.Location
import java.net.{URI, URLDecoder, URLEncoder}
import java.nio.charset.StandardCharsets
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec
import java.util.Base64

object OAuthConfig {
  val clientId: String = sys.env.getOrElse("OAUTH_CLIENT_ID", "ml-inference-server")
  val clientSecret: String = sys.env.getOrElse("OAUTH_CLIENT_SECRET", "k8s-secret-ref")
  val authorizationEndpoint: String = sys.env.getOrElse("OAUTH_AUTH_ENDPOINT", "https://idp.internal.corp/oauth2/authorize")
  val tokenEndpoint: String = sys.env.getOrElse("OAUTH_TOKEN_ENDPOINT", "https://idp.internal.corp/oauth2/token")
  val allowedRedirectDomain: String = sys.env.getOrElse("ALLOWED_REDIRECT_DOMAIN", "ml-serve.internal.corp")
  val hmacSecret: String = sys.env.getOrElse("HMAC_SECRET", "k8s-mounted-secret")
}

object RedirectValidator {

  private val ALLOWED_SCHEMES = Set("https")

  def computeStateHmac(sessionId: String, redirectUri: String): String = {
    val mac = Mac.getInstance("HmacSHA256")
    val keySpec = new SecretKeySpec(OAuthConfig.hmacSecret.getBytes(StandardCharsets.UTF_8), "HmacSHA256")
    mac.init(keySpec)
    val data = s"$sessionId|$redirectUri"
    Base64.getUrlEncoder.withoutPadding.encodeToString(mac.doFinal(data.getBytes(StandardCharsets.UTF_8)))
  }

  def validateRedirectUri(redirectUri: String): Boolean = {
    try {
      val decoded = URLDecoder.decode(redirectUri, StandardCharsets.UTF_8.name())
      val uri = new URI(decoded)
      val scheme = Option(uri.getScheme).map(_.toLowerCase).getOrElse("")
      val host = Option(uri.getHost).map(_.toLowerCase).getOrElse("")

      if (!ALLOWED_SCHEMES.contains(scheme)) return false
      if (uri.getPort > 0 && uri.getPort != 443) return false

      // Validate the host matches our allowed domain
      isAllowedHost(host)
    } catch {
      case _: Exception => false
    }
  }

  private def isAllowedHost(host: String): Boolean = {
    val allowedDomain = OAuthConfig.allowedRedirectDomain.toLowerCase
    // Host must be exactly the allowed domain or a subdomain of it
    host == allowedDomain || host.endsWith("." + allowedDomain)
  }

  def normalizeRedirectUri(redirectUri: String): String = {
    val decoded = URLDecoder.decode(redirectUri, StandardCharsets.UTF_8.name())
    val uri = new URI(decoded)
    // Reconstruct to normalize - use getRawPath to preserve encoding in path
    val normalizedScheme = uri.getScheme.toLowerCase
    val normalizedHost = uri.getHost.toLowerCase
    val port = if (uri.getPort == 443 || uri.getPort <= 0) "" else s":${uri.getPort}"
    val path = Option(uri.getRawPath).getOrElse("/")
    val query = Option(uri.getRawQuery).map(q => s"?$q").getOrElse("")
    val fragment = Option(uri.getRawFragment).map(f => s"#$f").getOrElse("")
    s"$normalizedScheme://$normalizedHost$port$path$query$fragment"
  }
}

object InferenceAuthRoutes {

  def routes: Route = {
    pathPrefix("oauth2") {
      path("login") {
        get {
          parameters("redirect_uri", "session_id") { (redirectUri, sessionId) =>
            if (RedirectValidator.validateRedirectUri(redirectUri)) {
              val normalized = RedirectValidator.normalizeRedirectUri(redirectUri)
              val state = RedirectValidator.computeStateHmac(sessionId, normalized)
              val encodedRedirect = URLEncoder.encode(normalized, StandardCharsets.UTF_8.name())
              val authUrl = s"${OAuthConfig.authorizationEndpoint}?client_id=${OAuthConfig.clientId}&redirect_uri=$encodedRedirect&state=$state&response_type=code&scope=openid+inference"
              redirect(authUrl, StatusCodes.Found)
            } else {
              complete(StatusCodes.BadRequest, "Invalid redirect URI")
            }
          }
        }
      } ~
      path("callback") {
        get {
          parameters("code", "state", "redirect_uri", "session_id") { (code, state, redirectUri, sessionId) =>
            val expectedState = RedirectValidator.computeStateHmac(sessionId, redirectUri)
            if (state == expectedState) {
              // State matches - redirect is authenticated
              // In production: exchange code for token first
              redirect(redirectUri, StatusCodes.Found)
            } else {
              complete(StatusCodes.Forbidden, "Invalid state parameter")
            }
          }
        }
      }
    } ~
    pathPrefix("v1" / "inference") {
      path("predict") {
        post {
          // ML inference endpoint - requires valid session
          complete(StatusCodes.OK, "{\"prediction\": [0.95, 0.03, 0.02]}")
        }
      }
    }
  }
}
